local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9906efb91f1918c9"] = { "L'anziana Totem Rabbioso passa le sue giornate nella ⟦Valley of the Watchers=Valle dei Guardiani⟧, nel deserto di Tanaris.", "." },
  ["991fde5066f42396"] = { "Il vento sussurra a chi sa ascoltare...\n\nLo senti?", "." },
  ["9923a37285cf1cec"] = { "%s segue {name} docilmente.", "." },
  ["9927b4122b9b7686"] = { "Ascolta chi è più anziano di te, {name}. Se hai una volontà forte e tanta dedizione, non c'è potere che tu non possa controllare.", "." },
  ["9928acbbddc5cc57"] = { "Assolutamente!", "." },
  ["9928acc8ddc5cc64"] = { "Assolutamente.", "." },
  ["992e840cddb7335b"] = { "Carne fresca!", "." },
  ["9930eacdd0247f58"] = { "Salute. Insegno ai maghi tra i non morti, e tu sei <un/una> <mago/maga>.", "." },
  ["99397735e582c0bc"] = { "Ma certo che ti amo, Staffron. E mi addolora vederti soffrire così.", "." },
  ["993a94ddc0e692a7"] = { "Maledetta Brewers' League! Hanno accesso a tutti gli ingredienti migliori, mentre noi siamo bloccati qui a raspare per un po' di grano e luppolo!\n\nMi piacerebbe proprio fargli assaggiare un po' di giustizia dal gusto amaro...", "." },
  ["993aafb83abb8a8a"] = { "Guardie! Aiutatemi!", "." },
  ["9943eff7753b9561"] = { "Che le esecuzioni abbiano inizio!", "." },
  ["994baa12b0b8799a"] = { "Ti sembra che io sia {class}? E ora sparisci, prima che mi venga voglia di oliare la mia lama... nel tuo sangue.", "." },
  ["99521cdcf30086a6"] = { "Non ci cascherò mai, <sciocco/sciocca>! Se vuoi battaglia, sarà alle mie condizioni e nella mia tana.", "." },
  ["995502b9f228eb72"] = { "La piccola vuole la sua bambola!", "." },
  ["9959fa7efc486845"] = { "Perché mai vorresti parlare con Kaplak? Lascia perdere. Cercalo in cima alla tana nell'angolo sud-ovest di ⟦Razor Hill=Tranciacolle⟧. Solo, tieni le mani nelle tue tasche!", "." },
  ["99669b3c05d03d24"] = { "Hai superato la prova, ben fatto! Ora il tuo addestramento può continuare.", "." },
  ["9967663cff52e929"] = { "Ho perso la cura, Doc! Dimmi che ne hai ancora!!!", "." },
  ["996b848aba6d8557"] = { "Prendetele finché sono belle fresche! Pagnotte di pane qui!", "." },
  ["99704438ac9e3741"] = { "Pensavi che il tuo tradimento sarebbe stato dimenticato? Perso nell'insabbiamento accuratamente orchestrato della mia morte? Sangue del mio sangue, la lama ha sentito la tua crudeltà a lungo dopo che il mio cuore aveva smesso di battere. E nella morte, ho saputo ciò che avevi fatto. Ma ora le catene di Kel'Thuzad non mi trattengono più. Vengo a rendere giustizia. IO SONO IL BRANDICENERE.", "." },
  ["9974d58d1f626b98"] = { "<Tarsis ti afferra debolmente per il colletto. Anche nella morte, vedi nei suoi occhi un potere inimmaginabile.>\n\nDavvero? Allora ascolta bene, perché altre sciocchezze stanno per uscire dalle mie labbra. In questa cittadella troverai l'opera della mia vita: il luogo esatto di ogni frammento del bastone spezzato.", "." },
  ["997db3c26abfe9b4"] = { "Un altro a terra!", "." },
  ["997f3c3e15ee8b95"] = { "Pescare mi sembra una buona idea.", "." },
  ["9985e6205ef6f272"] = { "{name}, la ⟦Stormpike Guard=Guardia dei Piccatonante⟧ ha bisogno del tuo aiuto nella battaglia contro il ⟦Frostwolf Clan=Clan Lupi Bianchi⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧, ora più che mai. E anche le occasioni di onore e fama sono più grandi che mai! Ti unirai alla battaglia?", "." },
  ["998915a77fd56677"] = { "%s si batte il petto, chiamando aiuto!", "." },
  ["998f06fc0f809486"] = { "Ho perso la mia ⟦Mace of Unending Life=Mazza della Vita Eterna⟧. Puoi sostituirmela?", "." },
  ["99b287032fdd1ca7"] = { "DING! 428.000 gradi Kraklenheit, esatti! Beh, all'incirca. Quasi. Più o meno da quelle parti...", "." },
  ["99b6083ac8e2b2c0"] = { "Se c'è una cosa che sappiamo, è che Arugal è responsabile dei worgen di ⟦Silverpine=Pinargento⟧. Che siano sue macchinazioni o altro. Ciò che non sappiamo è come si diffonde.\r\n\nMentre cerco un modo per fermare la maledizione, la nostra priorità è contenerla. Sembra che questa afflizione non possa infettare i Reietti come noi, ma un folto gruppo di umani si è radunato presso il Muro dei Mantogrigio.\r\n\nVai al muro ed elimina questi profughi prima che abbiano la possibilità di diventare servitori di Arugal.", "." },
  ["99b71b9393d3e6c9"] = { "Dopo l'attacco dei makrura, capimmo che il Gallant non sarebbe sopravvissuto a un altro. Così io e i pochi marinai superstiti abbandonammo la mia nave.\n\nOra siamo a terra e presto partiremo per il ⟦Nijel's Point=Presidio di Nijel⟧, ma molti pericoli ci separano dalla salvezza, e temo che ⟦Desolace=Desolanda⟧ ci divorerà.\n\nScrivo queste righe nella speranza che qualcuno venga a sapere della nostra sorte e un giorno ci vendichi dei mostri marini che furono la nostra rovina.", "." },
  ["99c037c76bcf75d7"] = { "Cosa posso fare per te, {race}?", "." },
  ["99c10c82e3d45f58"] = { "Presto il Flagello dominerà il mondo!", "." },
  ["99c4ac69375ae33b"] = { "%s va in frantumi, liberando l'anima che conteneva.", "." },
  ["99cd226b63024674"] = { "Ti comporti come se fosse la miglior robaccia che abbia mai visto. Certo, è passabile, ma roba così 'passabile' la vedo tutti i giorni. Facciamo così: trova un modo per lasciarmi a bocca aperta, e ti insegnerò cose che fanno sorridere i nani nel sonno.", "." },
  ["99ce976528504dc5"] = { "Aiuto! Mi insegue uno sciame di api!", "." },
  ["99cef5d2a0bd34d9"] = { "Questo raggio di luna conduce a ⟦Undercity=Sepulcra⟧. Avviati quando te la senti.", "." },
  ["99dc096e1ffa2fbb"] = { "Mi metto subito al lavoro, {name}.", "." },
  ["99f1ba99d4a1b91a"] = { "Qui a Brill non abbiamo una banca, per quella dovrai andare a ⟦Undercity=Sepulcra⟧. In fondo alle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧, a sud, ci sono degli ascensori che ti porteranno giù a ⟦Undercity=Sepulcra⟧. Una volta lì, chiedi a uno dei guardiani di ⟦Undercity=Sepulcra⟧ indicazioni più precise.", "." },
  ["99f98345d038c141"] = { "Barnil, mi sa che ho perso il Capitolo II.", "." },
  ["99f989ecd03a5fae"] = { "Barnil, mi sa che ho perso il Capitolo IV.", "." },
  ["99faba03f89906d9"] = { "Devi essere proprio alle strette per vagare in queste ⟦Badlands=Maleterre⟧, {class}. Alle strette come me.\n\nO forse sei qui perché ti manca qualche rotella. Come a me.", "." },
  ["99fd246e7872d1c3"] = { "Sai che sono il comandante supremo della ⟦Might of Kalimdor=Forza di Kalimdor⟧.", "." },
  ["99fffef74a9650b8"] = { "Lo riporterai in questo mondo, campione.", "." },
})
